  "ddp_test_source": "import os\nimport sys\nimport tempfile\nimport unittest\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\nfrom pathlib import Path\n\nTREE = Path(os.environ.get('CANDIDATE_TREE', Path(__file__).resolve().parents[1])).resolve()\nsys.path.insert(0, str(TREE))\nfrom model import RQVAE\nfrom train_rqvae import _tokenizer_config\n\ndef _rank_worker(rank, rendezvous, output):\n    dist.init_process_group('gloo', init_method='file://' + rendezvous, rank=rank, world_size=2)\n    try:\n        torch.manual_seed(1234)\n        cfg = _tokenizer_config()\n        cfg.hidden_sizes = (8,)\n        cfg.codebook_num = 1\n        cfg.codebook_size = (4,)\n        cfg.codebook_dim = 3\n        model = RQVAE(cfg, in_dim=5)\n        # Actual multi-process DDP wrapping and gradient synchronization.\n        model = torch.nn.parallel.DistributedDataParallel(model)\n        x = torch.tensor([[rank + 1., 2., 3., 4., 5.], [2., 1., 0., 1., 2.]])\n        all_x = torch.cat((x, torch.ones(2, 5)), dim=0)\n        anchor = torch.tensor([0, 1])\n        target = torch.tensor([1, 2])\n        loss, _, _, _ = model(x, all_embeddings=all_x, edge_anchor=anchor, edge_target=target)\n        loss.backward()\n        grads = [p.grad.detach().clone() for p in model.module.parameters() if p.grad is not None]\n        params = [p.detach().clone() for p in model.module.parameters()]\n        local = torch.cat([v.reshape(-1) for v in grads + params])\n        gathered = [torch.empty_like(local) for _ in range(2)]\n        # Gather each rank's independently computed post-backward values.\n        dist.all_gather(gathered, local)\n        if rank == 0:\n            torch.save([v.cpu() for v in gathered], output)\n        # Make the optimizer update on both ranks, from each rank's local batch.\n        opt = torch.optim.SGD(model.parameters(), lr=0.01)\n        opt.step()\n        updated = torch.cat([p.detach().reshape(-1) for p in model.module.parameters()])\n        gathered_updates = [torch.empty_like(updated) for _ in range(2)]\n        dist.all_gather(gathered_updates, updated)\n        if rank == 0:\n            torch.save([v.cpu() for v in gathered_updates], output + '.updated')\n    finally:\n        dist.destroy_process_group()\n\nclass CandidateDDPTest(unittest.TestCase):\n    def test_two_real_ranks_gather_equal_gradients_parameters_and_updates(self):\n        self.assertTrue(torch.distributed.is_available())\n        with tempfile.TemporaryDirectory() as d:\n            rendezvous = os.path.join(d, 'rendezvous')\n            output = os.path.join(d, 'gather.pt')\n            mp.spawn(_rank_worker, args=(rendezvous, output), nprocs=2, join=True)\n            gathered = torch.load(output, map_location='cpu', weights_only=True)\n            updated = torch.load(output + '.updated', map_location='cpu', weights_only=True)\n            self.assertEqual(len(gathered), 2)\n            self.assertFalse(torch.equal(gathered[0], torch.zeros_like(gathered[0])))\n            torch.testing.assert_close(gathered[0], gathered[1], rtol=1e-5, atol=1e-6)\n            torch.testing.assert_close(updated[0], updated[1], rtol=1e-5, atol=1e-6)\n\nif __name__ == '__main__':\n    unittest.main()\n",
  "entrypoint_test_source": "import json\nimport os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\nimport numpy as np\nimport pandas as pd\nimport torch\n\nTREE = Path(os.environ.get('CANDIDATE_TREE', Path(__file__).resolve().parents[1])).resolve()\nsys.path.insert(0, str(TREE))\nimport train_rqvae as trainer\n\nclass CandidateEntrypointTest(unittest.TestCase):\n    def test_real_trainer_main_writes_checkpoint_sid_and_uses_transition_loss(self):\n        with tempfile.TemporaryDirectory() as d:\n            root = Path(d)\n            embeddings = np.asarray([[.1, .2, .3, .4], [.2, .1, .4, .3], [.4, .3, .2, .1], [.3, .4, .1, .2]], dtype=np.float32)\n            emb_path = root / 'emb.npy'\n            np.save(emb_path, embeddings)\n            frame = pd.DataFrame({'user': [1, 1, 2, 2], 'history': [[0], [0, 1], [2], [2, 3]], 'target': [1, 2, 3, 0]})\n            train_path = root / 'train.parquet'\n            frame.to_parquet(train_path)\n            ckpt, sid_path, json_path = root / 'model.pth', root / 'sid.npy', root / 'sid.json'\n            config = dict(EMBEDDING_FILE=emb_path, TRAIN_FILE=train_path, CHECKPOINT=ckpt, OUTPUT_SID=sid_path, OUTPUT_JSON=json_path, METRICS_PATH=root/'metrics.jsonl', LOG_DIR=root/'logs', EPOCHS=1, BATCH_SIZE_PER_RANK=4, HIDDEN_SIZES=(8,), CODEBOOK_NUM=3, CODEBOOK_SIZE=(4, 4, 4), CODEBOOK_DIM=3, PCA_DIM=0, XAVIER_INIT=True, WARMUP_EPOCHS=0, EVAL_INTERVAL=1, NUM_WORKERS=0, GRADIENT_CLIP_NORM=1.0)\n            for name, value in config.items():\n                setattr(trainer, name, value)\n            calls = []\n            original_forward = trainer.RQVAE.forward\n            def observed_forward(model, *args, **kwargs):\n                result = original_forward(model, *args, **kwargs)\n                calls.append((kwargs.get('all_embeddings') is not None, kwargs.get('edge_anchor') is not None, float(result[2].detach())))\n                return result\n            with patch.object(trainer.RQVAE, 'forward', observed_forward):\n                trainer.main()\n            self.assertTrue(calls, 'trainer.main did not execute model forward')\n            self.assertTrue(all(a and b for a, b, _ in calls), 'real loss path omitted full item set or transition edges')\n            self.assertTrue(any(np.isfinite(t) and t > 0 for _, _, t in calls), 'transition loss was not active')\n            self.assertTrue(ckpt.is_file())\n            saved = torch.load(ckpt, map_location='cpu', weights_only=False)\n            self.assertEqual(saved['epoch'], 1)\n            self.assertEqual(saved['selection'], 'final_epoch')\n            self.assertTrue(saved['state_dict'])\n            self.assertTrue(sid_path.is_file())\n            sid = np.load(sid_path)\n            self.assertEqual(sid.shape, (4, 4))\n            self.assertEqual(len(np.unique(sid, axis=0)), 4)\n            exported = json.loads(json_path.read_text())\n            self.assertEqual(len(exported), 4)\n            self.assertEqual([exported[str(i)] for i in range(4)], sid.tolist())\n\nif __name__ == '__main__':\n    unittest.main()\n"
